/* Yu-Gi-Oh! internals shared by src/ygo (the rules themselves are EDOPro's: ygo_edo.c). */
#ifndef MOEMON_YGO_INTERNAL_H
#define MOEMON_YGO_INTERNAL_H
#include "ygo/duel.h"

#define NO_OBJ 0xFF

/* Fusion Monsters' materials, from their text (ygo_fusions.c, generated by tools/ygo/gen_catalog.py): what the special
 * duelists' decks are built around */
#define YGO_MAT_ANY 0x8000      /* | race: any monster of that race (YGO_RACE_*) */
#define YGO_MAT_ATTR 0x4000     /* | attribute */
struct YgoFusion
{
    uint16_t card;
    uint16_t materials[5];
};
const struct YgoFusion *Ygo_FusionOf(unsigned card);
/* The opponents' decks of the Game Boy Advance Yu-Gi-Oh! games (ygo_npc_decks.c, generated by
 * tools/ygo/rate_npc_decks.sh), weakest first: rating is their Elo from AI-against-AI duels */
struct YgoNpcDeck
{
    const char *name, *game, *gameName;
    uint16_t rating;
    uint8_t count;
    const uint16_t *cards;
};
extern const struct YgoNpcDeck gYgoNpcDecks[];
extern const unsigned gYgoNpcDeckCount;
#endif
